function hx(h){h=h.replace('#','');return {r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255};}
function sol(h,o){return {type:'SOLID',color:hx(h),opacity:(o===undefined?1:o)};}
const W={r:'Regular',m:'Medium',sb:'Semi Bold',b:'Bold'};
function T(p,o,c){
  const t=figma.createText();t.name=o.name||'T';
  t.fontName={family:'Inter',style:W[o.st||'r']};t.characters=c;
  t.fontSize=o.sz||16;t.lineHeight={unit:'PERCENT',value:(o.lh||1.45)*100};
  if(o.ls!==undefined){t.letterSpacing={unit:'PERCENT',value:o.ls};}
  t.fills=[sol(o.c||P.ink)];t.textAlignHorizontal=o.al||'LEFT';
  p.appendChild(t);t.textAutoResize='HEIGHT';t.resize(o.w||300,12);
  t.x=o.x||0;t.y=o.y||0;return t;
}
function F(p,o){
  const f=figma.createFrame();f.name=o.name||'F';f.resize(o.w,o.h);
  f.fills=o.fill?[sol(o.fill)]:[];
  if(o.r){f.cornerRadius=o.r;}
  if(o.stroke){f.strokes=[sol(o.stroke)];f.strokeWeight=o.sw||1;}
  if(o.clip){f.clipsContent=true;}
  p.appendChild(f);f.x=o.x||0;f.y=o.y||0;return f;
}
function IMG(p,o){
  const r=figma.createRectangle();r.name=o.name||'Image';r.resize(o.w,o.h);
  r.cornerRadius=o.r||0;r.fills=[{type:'IMAGE',imageHash:o.hash,scaleMode:'FILL'}];
  p.appendChild(r);r.x=o.x||0;r.y=o.y||0;return r;
}
async function IC(p,id,size,x,y,color){
  const c=await figma.getNodeByIdAsync(id);const i=c.createInstance();p.appendChild(i);
  i.rescale(size/Math.max(c.width,c.height));
  i.findAll(function(n){return n.type==='VECTOR';}).forEach(function(v){
    if(v.fills.length){v.fills=[sol(color)];}
    if(v.strokes.length){v.strokes=[sol(color)];}
  });
  i.x=x;i.y=y;return i;
}
