   .forEach(function(n){const s=sum(n.reactions);if(s){l[n.name]=s[0];}});
  out.links[fr.name]=l;
});
out.flow=(PG.flowStartingPoints||[]).map(function(f){return f.name+' -> '+f.nodeId;});
